export default function MenuCard({
  item,
  quantity,
  addToCart,
  removeFromCart
}) {
  const outOfStock = item.stock <= 0;

  const isTopRated = (item.avg_rating || 0) >= 4.5;
  const isTopSold = (item.sold_count || 0) >= 10;

  return (
    <div className="menu-card">

      {/* Badges */}
      <div className="menu-badges">
        {isTopSold && <span className="badge popular">🔥 Popular</span>}
        {isTopRated && <span className="badge top-rated">⭐ Top Rated</span>}
      </div>

      <h4>{item.name}</h4>
      <p className="price">₹{item.price}</p>

      <p className="rating">
        ⭐ {item.avg_rating || 0} | Sold: {item.sold_count || 0}
      </p>

      <p className={`stock ${outOfStock ? "out" : ""}`}>
        {outOfStock ? "Out of Stock" : `Stock: ${item.stock}`}
      </p>

      {/* Cart controls */}
      {!outOfStock ? (
        quantity === 0 ? (
          <button className="add-btn" onClick={() => addToCart(item)}>
            ADD
          </button>
        ) : (
          <div className="qty-controls">
            <button
              className="qty-btn"
              onClick={() => removeFromCart(item.id)}
            >
              −
            </button>

            <span className="qty-number">{quantity}</span>

            <button
              className="qty-btn"
              onClick={() => addToCart(item)}
              disabled={quantity >= item.stock}
            >
              +
            </button>
          </div>
        )
      ) : (
        <button className="add-btn disabled" disabled>
          Unavailable
        </button>
      )}
    </div>
  );
}
